SERVE = ("OVERHEAD_MS = 20     # бір шақырудың тұрақты бағасы: желі, модельді іске қосу\n"
         "PER_ITEM_MS = 2      # бір объектінің есептеу бағасы\n\n"
         "def batch_stats(b):\n"
         "    t = OVERHEAD_MS + PER_ITEM_MS * b\n"
         "    throughput = b / t * 1000          # объект/с\n"
         "    return t, throughput\n\n"
         "print(f'{\"пакет\":>6} {\"кешігу мс\":>10} {\"өткізу/с\":>10}')\n"
         "for b in (1, 4, 16, 64, 256):\n"
         "    t, thr = batch_stats(b)\n"
         "    print(f'{b:6} {t:10} {thr:10.0f}')\n"
         "print('өткізу шегі:', 1000 / PER_ITEM_MS, 'объект/с')\n\n"
         "SLO_MS = 60\n"
         "best = max((b for b in range(1, 1000) if batch_stats(b)[0] <= SLO_MS), key=lambda b: batch_stats(b)[1])\n"
         "print(f'кешігу ≤ {SLO_MS} мс шартында ең тиімді пакет: {best} (өткізу {batch_stats(best)[1]:.0f}/с)')")

