# ---------------------------------------------------------------- 8-сабақ
PSI = ("import bisect, math, random\n\n"
       "def histogram(xs, edges):\n"
       "    counts = [0] * (len(edges) - 1)\n"
       "    for x in xs:\n"
       "        counts[bisect.bisect_right(edges, x) - 1] += 1\n"
       "    n = len(xs)\n"
       "    return [max(c / n, 1e-4) for c in counts]          # нөл үлестен сақтану\n\n"
       "def psi(expected, actual):\n"
       "    return sum((a - e) * math.log(a / e) for e, a in zip(expected, actual))\n\n"
       "rng = random.Random(4)\n"
       "edges = [0, 40, 55, 70, 85, 101]\n"
       "train_scores = [min(100, max(0, rng.gauss(68, 12))) for _ in range(1500)]\n"
       "base = histogram(train_scores, edges)\n"
       "for name, mu, sd in [('келесі апта', 68, 12), ('жаңа мектеп қосылды', 62, 14), ('баға шкаласы өзгерді', 80, 8)]:\n"
       "    live = [min(100, max(0, rng.gauss(mu, sd))) for _ in range(1500)]\n"
       "    v = psi(base, histogram(live, edges))\n"
       "    level = 'тұрақты' if v < 0.1 else 'бақылау' if v < 0.25 else 'ДРЕЙФ: тексеру/қайта оқыту'\n"
       "    print(f'{name:22} PSI = {v:.3f} -> {level}')")

