AB = ("import math, random\n\n"
      "def z_test(x_a, n_a, x_b, n_b):\n"
      "    p = (x_a + x_b) / (n_a + n_b)\n"
      "    se = math.sqrt(p * (1 - p) * (1 / n_a + 1 / n_b))\n"
      "    return (x_b / n_b - x_a / n_a) / se\n\n"
      "def sample_size(p, delta, z_alpha=1.96, z_beta=0.84):\n"
      "    \"\"\"әр топқа: 5% маңыздылық, 80% қуат\"\"\"\n"
      "    return math.ceil(2 * (z_alpha + z_beta) ** 2 * p * (1 - p) / delta ** 2)\n\n"
      "print('0.20 -> 0.22 айырманы табу үшін әр топқа:', sample_size(0.21, 0.02), 'пайдаланушы')\n\n"
      "# Ерте «қарау» (peeking): A мен B ШЫН МӘНІНДЕ бірдей, бірақ әр 200 пайдаланушыдан кейін тексереміз\n"
      "rng = random.Random(2)\n"
      "experiments, false_wins_peek, false_wins_once = 300, 0, 0\n"
      "for _ in range(experiments):\n"
      "    xa = xb = n = 0\n"
      "    stopped = False\n"
      "    for step in range(20):\n"
      "        # 200 пайдаланушының сәттілік саны ≈ қалыпты үлестірім (биномның жуықтауы)\n"
      "        xa += round(rng.gauss(40, 32 ** 0.5))\n"
      "        xb += round(rng.gauss(40, 32 ** 0.5))\n"
      "        n += 200\n"
      "        if not stopped and abs(z_test(xa, n, xb, n)) > 1.96:\n"
      "            stopped = True\n"
      "    false_wins_peek += stopped\n"
      "    false_wins_once += abs(z_test(xa, n, xb, n)) > 1.96\n"
      "print(f'бір рет, соңында тексеру: жалған «жеңіс» {false_wins_once / experiments:.0%} (күтілетін ~5%)')\n"
      "print(f'20 рет қарау:             жалған «жеңіс» {false_wins_peek / experiments:.0%}')")

